<?php
declare(strict_types=1);
require_once __DIR__.'/../config/instructor_guard.php';
require_once __DIR__.'/../config/gemini.php';
header('Content-Type: application/json; charset=utf-8');
$reply=static function(int $status,array $data):never{http_response_code($status);echo json_encode(array_merge(['success'=>$status>=200&&$status<300],$data),JSON_UNESCAPED_UNICODE|JSON_INVALID_UTF8_SUBSTITUTE);exit;};
if(($_SERVER['REQUEST_METHOD']??'GET')!=='POST')$reply(405,['message'=>'طريقة الطلب غير مدعومة.']);
if(nbc_gemini_api_key()==='')$reply(503,['message'=>'مساعد التصحيح غير مهيأ. أضف مفتاح Gemini على الخادم.']);
$data=json_decode((string)file_get_contents('php://input'),true);if(!is_array($data))$reply(400,['message'=>'الطلب غير صالح.']);$attemptId=(int)($data['attempt_id']??0);$questionId=(int)($data['question_id']??0);$actor=(int)$currentInstructor['id'];
$stmt=$pdo->prepare("SELECT a.status,a.quiz_id,s.points,q.question_text,q.question_type,q.answer_key_json,q.grading_rubric,ans.answer_json FROM quiz_attempts a JOIN quiz_attempt_questions s ON s.attempt_id=a.id JOIN questions q ON q.id=s.question_id JOIN quiz_answers ans ON ans.attempt_id=a.id AND ans.question_id=s.question_id WHERE a.id=? AND s.question_id=?");$stmt->execute([$attemptId,$questionId]);$row=$stmt->fetch(PDO::FETCH_ASSOC);if(!$row||$row['status']!=='submitted'||!in_array($row['question_type'],['essay','short_answer','clinical_case'],true))$reply(404,['message'=>'لا توجد إجابة مقالية بانتظار المراجعة.']);
$owner=$pdo->prepare('SELECT z.created_by,c.instructor_id FROM quizzes z JOIN courses c ON c.id=z.course_id WHERE z.id=?');$owner->execute([$row['quiz_id']]);$role=$owner->fetch(PDO::FETCH_ASSOC);$admin=in_array('admin',$currentInstructor['roles']??[],true);if(!$admin&&(int)$role['created_by']!==$actor&&(int)$role['instructor_id']!==$actor)$reply(403,['message'=>'لا تملك صلاحية تصحيح هذه المحاولة.']);
$answer=json_decode((string)$row['answer_json'],true);if(is_array($answer))$answer=json_encode($answer,JSON_UNESCAPED_UNICODE);$prompt="Evaluate this student response only against the supplied question, model answer and rubric. Do not add medical facts beyond the reference. Return JSON {suggested_score:number, rationale:string, feedback:string}. Score must be between 0 and {$row['points']}. This is only a suggestion; an instructor will review and approve it.\nQuestion: {$row['question_text']}\nModel answer: ".((string)$row['answer_key_json']?:'Not provided')."\nRubric: ".((string)$row['grading_rubric']?:'Use accuracy, completeness, and clarity.')."\nStudent response: ".(string)$answer;
$result=nbc_gemini_generate([['role'=>'user','parts'=>[['text'=>$prompt]]]],'You assist a nursing instructor with grading suggestions. Return only a valid JSON object with suggested_score, rationale, and feedback. Do not include markdown.',['maxOutputTokens'=>1000,'responseMimeType'=>'application/json']);if(!$result['ok']){error_log('[Assessment Gemini grading] Provider HTTP '.(int)$result['status']);$reply(502,['message'=>'تعذر الحصول على اقتراح التصحيح من Gemini. تحقق من المفتاح وصلاحية Gemini API.']);}
$suggestion=json_decode($result['text'],true);if(!is_array($suggestion))$reply(502,['message'=>'رد التصحيح غير متوافق.']);$score=max(0,min((float)$row['points'],(float)($suggestion['suggested_score']??0)));$pdo->prepare('INSERT INTO assessment_event_logs (actor_user_id,event_key,entity_type,entity_id,details_json) VALUES (?,?,?,?,?)')->execute([$actor,'ai.grading_suggested','attempt',$attemptId,json_encode(['question_id'=>$questionId,'suggested_score'=>$score],JSON_UNESCAPED_UNICODE)]);$reply(200,['suggestion'=>['suggested_score'=>$score,'rationale'=>mb_substr((string)($suggestion['rationale']??''),0,3000),'feedback'=>mb_substr((string)($suggestion['feedback']??''),0,3000)],'message'=>'اقتراح فقط؛ راجعه واعتمده يدويًا.']);
